package config

import (
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"slices"
	"strings"
	"time"

	"github.com/17twenty/flow/internal/core"
	yaml "go.yaml.in/yaml/v3"
)

// LockPath is the name of the machine-written lock at the repository root.
const LockPath = ".flow.lock"

// LockVersion is the only lock schema version this build understands.
const LockVersion = 1

// lockHeader is written at the top of every lock, because the first thing
// anyone does with a generated file is try to edit it.
const lockHeader = "# generated by flow — do not edit; use flow doctor --fix"

// ObservationTTL is how long an observation's timestamp stands before it is
// refreshed even though nothing changed. Rewriting every timestamp on every
// run would put a diff in front of a reviewer that says nothing (spec 03 §3).
const ObservationTTL = 24 * time.Hour

// Follow-up states recorded in the lock (spec 07 §4).
const (
	// FollowUpOpen means the ticket is open and the work is outstanding.
	FollowUpOpen = "open"
	// FollowUpClosed means flow verified the work and closed the ticket.
	FollowUpClosed = "closed"
	// FollowUpDeclined means a person closed the ticket as not planned while
	// the configuration still asked for the work. Flow leaves it closed and
	// says once how to write the decision down (issue #265).
	FollowUpDeclined = "declined"
)

// Lock is what flow learned about the world: the ids it resolved, what it
// observed and when, what it created, what it asked a human to do and what a
// human swore to. It is committed, so that the next run — on another machine,
// in CI — starts from the same knowledge (spec 03 §3).
//
// flow writes this file; people do not.
type Lock struct {
	// Version pins the lock schema.
	Version int `yaml:"version"`
	// FlowVersion is the build that last wrote the file.
	FlowVersion string `yaml:"flow_version"`
	// ConfigHash is the hash of the configuration this knowledge was gathered
	// for. When it changes, attestations against the changed inputs lapse.
	ConfigHash string `yaml:"config_hash"`
	// Resolved maps a configuration path to the identifier flow found for it.
	Resolved map[string]string `yaml:"resolved,omitempty"`
	// Observed records the canonical hash of each thing flow watches, and when
	// it last looked.
	Observed map[string]Observation `yaml:"observed,omitempty"`
	// Created is everything flow brought into existence. Nothing outside this
	// list is ever deleted (spec 06 §4).
	Created []Creation `yaml:"created,omitempty"`
	// FollowUps are the tickets flow opened for work it could not do itself.
	FollowUps []FollowUp `yaml:"followups,omitempty"`
	// Attestations are the checks a human has vouched for.
	Attestations []Attestation `yaml:"attestations,omitempty"`
}

// Observation is the canonical hash of something flow watches, and the moment
// it was last seen in that state.
type Observation struct {
	// Hash is the canonical hash of the observed state, "sha256:…".
	Hash string `yaml:"hash"`
	// At is when the hash was last confirmed.
	At time.Time `yaml:"at"`
}

// Creation records something flow made, so that it can be told apart from
// whatever was already there.
type Creation struct {
	// Kind is what was created, for example tracker.status_option.
	Kind string `yaml:"kind"`
	// ID is the provider's identifier for it.
	ID string `yaml:"id"`
	// Name is its display name at the time of creation.
	Name string `yaml:"name,omitempty"`
	// At is when flow created it.
	At time.Time `yaml:"at"`
}

// FollowUp is a ticket flow opened because it could not do the work itself —
// usually because the credential cannot, or the provider has no API for it.
type FollowUp struct {
	// Check is the doctor check id the follow-up belongs to.
	Check string `yaml:"check"`
	// Ticket is the tracker's key for the ticket, for example "#12".
	Ticket string `yaml:"ticket"`
	// Owner is who was asked to do it.
	Owner string `yaml:"owner,omitempty"`
	// OpenedAt is when flow filed it.
	OpenedAt time.Time `yaml:"opened_at"`
	// NudgedAt is when flow last commented to say it is still outstanding,
	// zero when it never has. It is what rations the nudge to one a week: the
	// ticket's own comment is edited in place, so the tracker cannot be asked
	// how long ago that was without reading every comment back (spec 07 §4).
	NudgedAt time.Time `yaml:"nudged_at,omitempty"`
	// State is open or closed.
	State string `yaml:"state"`
}

// Attestation is a human's word that something is true which flow cannot
// verify itself. It expires, because a promise about a system is only as good
// as the day it was made (spec 07 §8).
type Attestation struct {
	// Check is the doctor check id being attested.
	Check string `yaml:"check"`
	// By is who vouched for it.
	By string `yaml:"by"`
	// Note is what they said.
	Note string `yaml:"note,omitempty"`
	// At is when they said it.
	At time.Time `yaml:"at"`
	// ExpiresAt is when flow will ask again.
	ExpiresAt time.Time `yaml:"expires_at"`
	// Inputs is the canonical hash of the part of the configuration the
	// attestation was made against, so that editing an unrelated part of
	// `.flow.yaml` does not throw away every promise in the file (spec 07 §8).
	// Empty means the attestation predates the field and lapses with the whole
	// lock's ConfigHash instead.
	Inputs string `yaml:"inputs,omitempty"`
}

// NewLock returns an empty lock for the given flow version.
func NewLock(flowVersion string) *Lock {
	return &Lock{Version: LockVersion, FlowVersion: flowVersion}
}

// Hash returns the canonical hash form flow records in the lock.
func Hash(data []byte) string {
	sum := sha256.Sum256(data)
	return "sha256:" + hex.EncodeToString(sum[:])
}

// Lookup returns a resolved value and whether it is there.
func (l *Lock) Lookup(key string) (string, bool) {
	value, ok := l.Resolved[key]
	return value, ok
}

// Resolve records the identifier found for a configuration path.
func (l *Lock) Resolve(key, value string) {
	if l.Resolved == nil {
		l.Resolved = map[string]string{}
	}
	l.Resolved[key] = value
}

// Observe records that key was seen with this hash at this moment.
//
// The timestamp is only moved when the hash changed or when the last one is
// over [ObservationTTL] old. A lock whose only change is a row of fresh
// timestamps is a diff that wastes a reviewer's attention (spec 03 §3).
func (l *Lock) Observe(key, hash string, now time.Time) {
	if l.Observed == nil {
		l.Observed = map[string]Observation{}
	}
	now = now.UTC().Truncate(time.Second)
	// A clock that went backwards is not a reason to rewrite the file, so the
	// timestamp only moves when the gap is a full TTL forward.
	if previous, ok := l.Observed[key]; ok && previous.Hash == hash && now.Sub(previous.At.UTC()) < ObservationTTL {
		return
	}
	l.Observed[key] = Observation{Hash: hash, At: now}
}

// Record remembers something flow created. A record replaces the one about
// the same thing: by identifier when both have one, by name otherwise. A
// required status check is only ever its name, and matching two empty ids
// made the second check flow required overwrite the record of the first.
func (l *Lock) Record(c Creation) {
	c.At = c.At.UTC().Truncate(time.Second)
	for i, existing := range l.Created {
		same := existing.ID == c.ID
		if existing.ID == "" || c.ID == "" {
			same = existing.ID == c.ID && existing.Name == c.Name
		}
		if existing.Kind == c.Kind && same {
			l.Created[i] = c
			return
		}
	}
	l.Created = append(l.Created, c)
}

// legacyCreationKinds are kinds an earlier flow wrote and this one reads as
// their proper names. The kind used to be the item id with its last "s"
// trimmed, which made `forge.required_status` a `forge.required_statu`
// (issue #204).
var legacyCreationKinds = map[string]string{
	"forge.required_statu": "forge.required_status",
}

// Normalise puts the lock in its canonical form: UTC timestamps truncated to
// the second, and every list in a stable order. Two runs that learned the same
// things must write the same bytes (spec 03 §3).
func (l *Lock) Normalise() {
	for key, observation := range l.Observed {
		observation.At = observation.At.UTC().Truncate(time.Second)
		l.Observed[key] = observation
	}
	for i := range l.Created {
		l.Created[i].At = l.Created[i].At.UTC().Truncate(time.Second)
		if kind, ok := legacyCreationKinds[l.Created[i].Kind]; ok {
			l.Created[i].Kind = kind
		}
	}
	for i := range l.FollowUps {
		l.FollowUps[i].OpenedAt = l.FollowUps[i].OpenedAt.UTC().Truncate(time.Second)
		l.FollowUps[i].NudgedAt = l.FollowUps[i].NudgedAt.UTC().Truncate(time.Second)
	}
	for i := range l.Attestations {
		l.Attestations[i].At = l.Attestations[i].At.UTC().Truncate(time.Second)
		l.Attestations[i].ExpiresAt = l.Attestations[i].ExpiresAt.UTC().Truncate(time.Second)
	}

	slices.SortStableFunc(l.Created, func(a, b Creation) int {
		return strings.Compare(a.Kind+"\x00"+a.ID, b.Kind+"\x00"+b.ID)
	})
	slices.SortStableFunc(l.FollowUps, func(a, b FollowUp) int {
		return strings.Compare(a.Check+"\x00"+a.Ticket, b.Check+"\x00"+b.Ticket)
	})
	slices.SortStableFunc(l.Attestations, func(a, b Attestation) int {
		return strings.Compare(a.Check+"\x00"+a.By, b.Check+"\x00"+b.By)
	})
}

// Bytes renders the lock exactly as it is written to disk.
func (l *Lock) Bytes() ([]byte, error) {
	l.Normalise()
	if l.Version == 0 {
		l.Version = LockVersion
	}

	var out strings.Builder
	out.WriteString(lockHeader)
	out.WriteString("\n")

	encoder := yaml.NewEncoder(&out)
	encoder.SetIndent(2)
	if err := encoder.Encode(l.node()); err != nil {
		return nil, fmt.Errorf("render the lock: %w", err)
	}
	if err := encoder.Close(); err != nil {
		return nil, fmt.Errorf("render the lock: %w", err)
	}
	return []byte(out.String()), nil
}

// WriteLock writes the lock to path atomically: a reader always sees either
// the previous file or the whole new one, never half of either.
func WriteLock(path string, l *Lock) error {
	data, err := l.Bytes()
	if err != nil {
		return core.Errorf(core.ErrValidation, "write %s", path).WithWhy("%s", err)
	}

	mode := os.FileMode(0o644)
	if info, err := os.Stat(path); err == nil {
		mode = info.Mode().Perm()
	}

	dir := filepath.Dir(path)
	tmp, err := os.CreateTemp(dir, filepath.Base(path)+".*.tmp")
	if err != nil {
		return core.Errorf(core.ErrValidation, "write %s", path).WithWhy("%s", err)
	}
	tmpName := tmp.Name()
	defer os.Remove(tmpName)

	fail := func(err error) error {
		tmp.Close()
		return core.Errorf(core.ErrValidation, "write %s", path).WithWhy("%s", err)
	}
	if _, err := tmp.Write(data); err != nil {
		return fail(err)
	}
	if err := tmp.Chmod(mode); err != nil {
		return fail(err)
	}
	if err := tmp.Sync(); err != nil {
		return fail(err)
	}
	if err := tmp.Close(); err != nil {
		return core.Errorf(core.ErrValidation, "write %s", path).WithWhy("%s", err)
	}
	if err := os.Rename(tmpName, path); err != nil {
		return core.Errorf(core.ErrValidation, "write %s", path).WithWhy("%s", err)
	}
	syncDir(dir)
	return nil
}

// syncDir flushes a directory entry so the rename survives a power cut. Not
// every platform lets us open a directory; where it does not, the rename is
// still atomic and only durability is weaker, so the error is not worth
// failing a write over.
func syncDir(dir string) {
	handle, err := os.Open(dir)
	if err != nil {
		return
	}
	defer handle.Close()
	_ = handle.Sync()
}

// LoadLock reads and decodes the lock at path. A missing lock is not an error:
// it means flow has not learned anything yet.
func LoadLock(path string) (*Lock, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, core.Errorf(core.ErrNotFound, "read %s", path).
				WithWhy("the file does not exist").
				WithFix("run flow doctor --fix to create it")
		}
		return nil, core.Errorf(core.ErrValidation, "read %s", path).WithWhy("%s", err)
	}
	return ParseLock(data, path)
}

// ParseLock decodes src as a `.flow.lock`. Decoding is as strict as it is for
// `.flow.yaml`: flow wrote this file, so anything unexpected in it means the
// file was hand-edited or written by another version, and both are worth
// saying out loud.
func ParseLock(src []byte, path string) (*Lock, error) {
	if path == "" {
		path = LockPath
	}

	var doc yaml.Node
	if err := yaml.Unmarshal(src, &doc); err != nil {
		return nil, newParseError(path, translate(err, path, nil))
	}
	if doc.Kind == 0 {
		return nil, newParseError(path, []Problem{{
			Path:    path,
			Message: "the file is empty; delete it and run flow doctor --fix",
		}})
	}

	var lock Lock
	decoder := yaml.NewDecoder(strings.NewReader(string(src)))
	decoder.KnownFields(true)
	if err := decoder.Decode(&lock); err != nil && !errors.Is(err, io.EOF) {
		return nil, newParseError(path, translate(err, path, indexNodes(&doc)))
	}
	if lock.Version != LockVersion {
		return nil, newParseError(path, []Problem{{
			Path:    path,
			Line:    1,
			Column:  1,
			Message: fmt.Sprintf("lock version %d is not supported; this build writes version %d", lock.Version, LockVersion),
		}})
	}
	lock.Normalise()
	return &lock, nil
}

// node builds the document flow writes, rather than marshalling the struct, so
// that key order, list order and the compact shape of each record are flow's
// decision and not the encoder's.
func (l *Lock) node() *yaml.Node {
	root := blockMap()
	put := func(key string, value *yaml.Node) {
		root.Content = append(root.Content, scalar("!!str", key), value)
	}

	put("version", scalar("!!int", fmt.Sprint(l.Version)))
	put("flow_version", scalar("!!str", l.FlowVersion))
	put("config_hash", scalar("!!str", l.ConfigHash))

	if len(l.Resolved) > 0 {
		resolved := blockMap()
		for _, key := range sortedKeys(l.Resolved) {
			resolved.Content = append(resolved.Content, scalar("!!str", key), scalar("!!str", l.Resolved[key]))
		}
		put("resolved", resolved)
	}

	if len(l.Observed) > 0 {
		observed := blockMap()
		for _, key := range sortedKeys(l.Observed) {
			observation := l.Observed[key]
			observed.Content = append(observed.Content, scalar("!!str", key), record(
				"hash", scalar("!!str", observation.Hash),
				"at", timestamp(observation.At),
			))
		}
		put("observed", observed)
	}

	if len(l.Created) > 0 {
		created := blockSeq()
		for _, c := range l.Created {
			created.Content = append(created.Content, record(
				"kind", scalar("!!str", c.Kind),
				"id", scalar("!!str", c.ID),
				"name", scalar("!!str", c.Name),
				"at", timestamp(c.At),
			))
		}
		put("created", created)
	}

	if len(l.FollowUps) > 0 {
		followups := blockSeq()
		for _, f := range l.FollowUps {
			followups.Content = append(followups.Content, record(
				"check", scalar("!!str", f.Check),
				"ticket", scalar("!!str", f.Ticket),
				"owner", scalar("!!str", f.Owner),
				"opened_at", timestamp(f.OpenedAt),
				"nudged_at", optionalTimestamp(f.NudgedAt),
				"state", scalar("!!str", f.State),
			))
		}
		put("followups", followups)
	}

	if len(l.Attestations) > 0 {
		attestations := blockSeq()
		for _, a := range l.Attestations {
			attestations.Content = append(attestations.Content, record(
				"check", scalar("!!str", a.Check),
				"by", scalar("!!str", a.By),
				"note", scalar("!!str", a.Note),
				"at", timestamp(a.At),
				"expires_at", timestamp(a.ExpiresAt),
				"inputs", scalar("!!str", a.Inputs),
			))
		}
		put("attestations", attestations)
	}

	return root
}

// sortedKeys returns a map's keys in a stable order.
func sortedKeys[V any](m map[string]V) []string {
	keys := make([]string, 0, len(m))
	for key := range m {
		keys = append(keys, key)
	}
	slices.Sort(keys)
	return keys
}

// scalar builds a scalar node with an explicit tag, leaving quoting to the
// emitter, which quotes whatever would otherwise read as another type.
func scalar(tag, value string) *yaml.Node {
	return &yaml.Node{Kind: yaml.ScalarNode, Tag: tag, Value: value}
}

// timestamp renders a moment as RFC3339 in UTC, to the second.
func timestamp(t time.Time) *yaml.Node {
	return scalar("!!timestamp", t.UTC().Truncate(time.Second).Format(time.RFC3339))
}

// optionalTimestamp renders a moment, or an empty scalar that [record] drops,
// so that a follow-up nobody has had to chase yet carries no key at all.
func optionalTimestamp(t time.Time) *yaml.Node {
	if t.IsZero() {
		return scalar("!!str", "")
	}
	return timestamp(t)
}

// blockMap builds an empty mapping written one key per line.
func blockMap() *yaml.Node {
	return &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
}

// blockSeq builds an empty sequence written one item per line.
func blockSeq() *yaml.Node {
	return &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq"}
}

// record builds a mapping for one short entry in the lock's lists. Keys whose
// value is empty are left out.
func record(pairs ...any) *yaml.Node {
	node := blockMap()
	for i := 0; i+1 < len(pairs); i += 2 {
		key := pairs[i].(string)
		value := pairs[i+1].(*yaml.Node)
		if value.Value == "" {
			continue
		}
		node.Content = append(node.Content, scalar("!!str", key), value)
	}
	return node
}
